 "content": "from collections import deque


def transform(grid):
    """Return the unique foreground object whose bounding box is 4 by 4."""
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == dx == 0:
                            continue
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0
                                and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            q.append((ny, nx))
            min_r = min(y for y, x in cells)
            max_r = max(y for y, x in cells)
            min_c = min(x for y, x in cells)
            max_c = max(x for y, x in cells)
            if max_r - min_r + 1 == 4 and max_c - min_c + 1 == 4:
                objects.append([[int(grid[y][x] != 0) for x in range(min_c, max_c + 1)]
                                for y in range(min_r, max_r + 1)])
    if len(objects) != 1:
        raise ValueError(f"Expected one 4x4 object; found {len(objects)}")
    return objects[0]
